import heapq

def match(orders):
    trades = []
    buy_heap = []   # entries: (-price, seq, id)
    sell_heap = []  # entries: (price, seq, id)
    book = {}       # id -> {'side','price','qty','seq','active'}
    seq_counter = 0

    for order in orders:
        typ = order[0]

        if typ == 'cancel':
            oid = order[1]
            if oid in book and book[oid]['active'] and book[oid]['qty'] > 0:
                book[oid]['active'] = False
            continue

        if typ == 'limit':
            _, oid, side, price, qty = order
        elif typ == 'ioc':
            _, oid, side, price, qty = order
        elif typ == 'market':
            _, oid, side, qty = order
            price = None
        else:
            continue

        seq_counter += 1
        seq = seq_counter
        remaining = qty

        if side == 'buy':
            while remaining > 0 and sell_heap:
                top_price, top_seq, top_id = sell_heap[0]
                entry = book.get(top_id)
                if entry is None or not entry['active'] or entry['qty'] <= 0:
                    heapq.heappop(sell_heap)
                    continue
                if typ == 'market' or price >= top_price:
                    trade_qty = min(remaining, entry['qty'])
                    trades.append([oid, top_id, top_price, trade_qty])
                    remaining -= trade_qty
                    entry['qty'] -= trade_qty
                    if entry['qty'] == 0:
                        entry['active'] = False
                        heapq.heappop(sell_heap)
                else:
                    break

            if remaining > 0 and typ == 'limit':
                book[oid] = {'side': 'buy', 'price': price, 'qty': remaining, 'seq': seq, 'active': True}
                heapq.heappush(buy_heap, (-price, seq, oid))

        else:  # sell
            while remaining > 0 and buy_heap:
                top_neg_price, top_seq, top_id = buy_heap[0]
                top_price = -top_neg_price
                entry = book.get(top_id)
                if entry is None or not entry['active'] or entry['qty'] <= 0:
                    heapq.heappop(buy_heap)
                    continue
                if typ == 'market' or price <= top_price:
                    trade_qty = min(remaining, entry['qty'])
                    trades.append([top_id, oid, top_price, trade_qty])
                    remaining -= trade_qty
                    entry['qty'] -= trade_qty
                    if entry['qty'] == 0:
                        entry['active'] = False
                        heapq.heappop(buy_heap)
                else:
                    break

            if remaining > 0 and typ == 'limit':
                book[oid] = {'side': 'sell', 'price': price, 'qty': remaining, 'seq': seq, 'active': True}
                heapq.heappush(sell_heap, (price, seq, oid))

    return trades

